from flask_smorest import Blueprint, abort
from marshmallow import Schema, fields, validate
from app.models import Post
from app.extensions import db

blp = Blueprint("posts", "posts", url_prefix="/api/posts", description="Post operations")

class PostSchema(Schema):
    id = fields.Integer(dump_only=True)
    title = fields.String(required=True, validate=validate.Length(min=1, max=255))
    body = fields.String(allow_none=True)
    author_id = fields.Integer(dump_only=True)

@blp.route("/")
class Posts(blp.MethodView):
    @blp.response(200, PostSchema(many=True))
    def get(self):
        return db.session.execute(db.select(Post)).scalars().all()

    @blp.arguments(PostSchema)
    @blp.response(201, PostSchema)
    def post(self, data):  # data is the validated dict
        post = Post(**data, author_id=1)
        db.session.add(post)
        db.session.commit()
        return post

from flask import Flask, jsonify, render_template, request
from werkzeug.exceptions import HTTPException

app = Flask(__name__)

@app.errorhandler(404)
def not_found(err):
    # Return JSON for API routes, HTML for browser routes:
    if request.path.startswith("/api/"):
        return jsonify({"error": "not_found", "message": err.description}), 404
    return render_template("errors/404.html"), 404

@app.errorhandler(500)
def server_error(err):
    app.logger.exception("500 on %s", request.path)
    return render_template("errors/500.html"), 500

@app.errorhandler(Exception)
def unhandled(err):
    if isinstance(err, HTTPException):
        return err  # let Flask's default formatting kick in for abort()
    app.logger.exception("Unhandled on %s", request.path)
    return render_template("errors/500.html"), 500

